});

/** The servers and clients a suite opens, and a teardown that lets each server see its sockets close before it stops. */
export function trackedEngines(): {servers: HalServer[]; clients: WebSocket[]; closeAll: () => Promise<void>} {
  const servers: HalServer[] = [];
  const clients: WebSocket[] = [];
  const closeAll = async (): Promise<void> => {
    for (const client of clients.splice(0)) client.terminate();
    for (const hal of servers.splice(0)) {
      const {wss} = hal;
      await eventually(() => wss.clients.size === 0);
      await hal.stop();
    }
  };
  return {servers, clients, closeAll};
}
