new='''export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  // A list is not a turn and never waits on one; a frame after it on the session waits for it, so answers keep arrival order.
  const listing = new Map<string, Promise<void>>();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    const pending = listing.get(session.sessionId);
    if (validation.valid && validation.data.type === 'list_sessions') {
      const message = validation.data;
      const listed = (pending ?? Promise.resolve()).then(() => answerList(ws, session, sessionStore, message));
      listing.set(session.sessionId, listed);
      void listed.then(() => forgetListing(listing, session.sessionId, listed));
      return listed;
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    if (pending === undefined) return wsErrorHandler(ws, async () => answerFrame(ws, validation));
    return pending.then(() => wsErrorHandler(ws, async () => answerFrame(ws, validation)));
  };
}

// Only the newest list clears its session: a list queued behind it keeps the key until it settles too.
function forgetListing(listing: Map<string, Promise<void>>, sessionId: string, listed: Promise<void>): void {
  if (listing.get(sessionId) === listed) listing.delete(sessionId);
}

// The user is the connection's, never the frame's: validation strips any userId a client sends.
async function answerList(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
    sendSessionList(ws, summaries.map(toSummaryFrame));
  } catch (error) {
    log.error('ws', 'session list failed', {
      sessionId: session.sessionId,
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

// A Date does not survive JSON as a Date, so the frame carries what goes on the wire.
function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

